gWD(){return"\u06a9\u06c6\u0645\u0628\u06c6"},
gWC(){return"\u06a9\u06c6\u0645\u06ce\u0646 \u0626\u0627\u0645\u0627\u062f\u06d5\u06a9\u0631\u06cc \u06cc\u06ce\u0646 \u062c\u06c6\u0631\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u06a9\u0648 \u0647\u06d5\u0631 \u062f\u06d5\u0645 \u067e\u06ce\u06a9\u06a4\u06d5 \u062f\u0647\u06ce\u0646\u06d5 \u0686\u06ce\u06a9\u0631\u0646 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 \u0626\u06cc\u0645\u067e\u0644\u0627\u0646\u062a + \u062a\u0627\u062c) \u2014 \u0626\u06ce\u06a9\u06ce \u062f \u06a9\u06d5\u06cc\u0633\u06ce \u0646\u0648\u06cc \u062f\u0627 \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5 \u0628\u06c6 \u0626\u0627\u0645\u0627\u062f\u06d5\u06a9\u0631\u0646\u0627 \u0647\u06d5\u0645\u06cc \u0626\u06d5\u0646\u062f\u0627\u0645\u0627\u0646 \u067e\u06ce\u06a9\u06a4\u06d5."},
